CREATE TABLE admin_users (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, name TEXT NOT NULL DEFAULT 'Admin', role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE admin_sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES admin_users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE INDEX idx_sessions_expiry ON admin_sessions(expires_at);
CREATE TABLE login_attempts (id INTEGER PRIMARY KEY, identity TEXT NOT NULL, attempted_at INTEGER NOT NULL);
CREATE INDEX idx_attempts ON login_attempts(identity,attempted_at);
CREATE TABLE courses (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE batches (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', course_id TEXT REFERENCES courses(id), start_date TEXT, end_date TEXT, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE internships (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', course_id TEXT REFERENCES courses(id), start_date TEXT, end_date TEXT, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_batches_published ON batches(status,start_date);
CREATE INDEX idx_internships_published ON internships(status,start_date);
ALTER TABLE registrations ADD COLUMN batch_id TEXT REFERENCES batches(id);
ALTER TABLE registrations ADD COLUMN internship_id TEXT REFERENCES internships(id);
ALTER TABLE registrations ADD COLUMN admin_notes TEXT NOT NULL DEFAULT '';
ALTER TABLE registrations ADD COLUMN archived INTEGER NOT NULL DEFAULT 0;
ALTER TABLE registrations ADD COLUMN updated_at TEXT;
ALTER TABLE enquiries ADD COLUMN status TEXT NOT NULL DEFAULT 'New';
ALTER TABLE enquiries ADD COLUMN admin_notes TEXT NOT NULL DEFAULT '';
ALTER TABLE enquiries ADD COLUMN follow_up_date TEXT;
ALTER TABLE enquiries ADD COLUMN source TEXT NOT NULL DEFAULT 'website';
ALTER TABLE enquiries ADD COLUMN archived INTEGER NOT NULL DEFAULT 0;
ALTER TABLE enquiries ADD COLUMN updated_at TEXT;
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_audit_date ON audit_logs(created_at);
